package me.pikanote.companion;
import android.content.Context;import android.media.*;import org.json.JSONObject;import java.io.*;import java.nio.*;import java.time.Instant;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
final class PhoneRecorder {
 interface Listener{void event(JSONObject value);}
 static final int RATE=16000;final Context context;final Listener listener;final ExecutorService audio=Executors.newSingleThreadExecutor();Session current;
 static final class Session{final boolean ask;final String token,created=Instant.now().toString();final AtomicBoolean stop=new AtomicBoolean(),cancel=new AtomicBoolean();Session(String key,boolean isAsk){token=key;ask=isAsk;}}
 PhoneRecorder(Context context,Listener listener){this.context=context.getApplicationContext();this.listener=listener;}
 synchronized void start(String token)throws Exception{start(token,false);}
 synchronized void start(String token,boolean ask)throws Exception{PhoneVoice.fileName(token);if(current!=null)throw new IOException("Already recording");Session session=new Session(token,ask);current=session;audio.execute(()->record(session));}
 synchronized void stop(String token,boolean cancel){Session session=current;if(session==null||(!token.isEmpty()&&!session.token.equals(token)))return;if(cancel)session.cancel.set(true);session.stop.set(true);}
 synchronized boolean active(){return current!=null;}
 void emit(Session session,String state,long duration,String error){try{listener.event(new JSONObject().put("token",session.token).put("state",state).put("durationMs",duration).put("error",error));}catch(Exception ignored){}}
 static byte[] header(long bytes){return ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN).put(new byte[]{'R','I','F','F'}).putInt((int)(bytes+36)).put(new byte[]{'W','A','V','E','f','m','t',' '}).putInt(16).putShort((short)1).putShort((short)1).putInt(RATE).putInt(RATE*2).putShort((short)2).putShort((short)16).put(new byte[]{'d','a','t','a'}).putInt((int)bytes).array();}
 void record(Session session){AudioRecord mic=null;File file=null;long bytes=0;try{Store store=Store.get(context);file=store.safeFile((session.ask?".phone-ask-"+session.token+".wav":PhoneVoice.fileName(session.token))+".recording");if(session.cancel.get()||session.stop.get()){emit(session,"cancelled",0,"");return;}int minimum=AudioRecord.getMinBufferSize(RATE,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);if(minimum<=0)throw new IOException("Microphone does not support 16 kHz mono audio");mic=new AudioRecord(MediaRecorder.AudioSource.VOICE_RECOGNITION,RATE,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(minimum*2,8192));if(mic.getState()!=AudioRecord.STATE_INITIALIZED)throw new IOException("Microphone unavailable");try(RandomAccessFile out=new RandomAccessFile(file,"rw")){out.setLength(0);out.write(header(0));mic.startRecording();emit(session,"recording",0,"");byte[] buffer=new byte[2048];long last=0;while(!session.stop.get()&&bytes<32000L*600){int count=mic.read(buffer,0,buffer.length,AudioRecord.READ_BLOCKING);if(count<0)throw new IOException("Microphone read failed");count&=~1;if(count==0)continue;out.write(buffer,0,count);bytes+=count;long duration=bytes*1000/32000;if(duration-last>=200){emit(session,"recording",duration,"");last=duration;}}out.seek(0);out.write(header(bytes));out.getFD().sync();}
  if(session.cancel.get()||bytes<PhoneVoice.MIN_PCM){file.delete();emit(session,"cancelled",bytes*1000/32000,"");}else{File completed=store.safeFile((session.ask?".phone-ask-"+session.token+".wav":PhoneVoice.fileName(session.token)));java.nio.file.Files.move(file.toPath(),completed.toPath(),java.nio.file.StandardCopyOption.ATOMIC_MOVE);file=completed;if(session.ask)PhoneAsk.enqueue(store,session.token,"",completed.getName(),session.created);else PhoneVoice.enqueue(store,session.token,bytes*1000/32000,session.created);emit(session,"queued",bytes*1000/32000,"");}}
 catch(Exception error){if(file!=null&&bytes<PhoneVoice.MIN_PCM)file.delete();emit(session,"error",bytes*1000/32000,error.getMessage()==null?"Recording failed":error.getMessage());}
 finally{if(mic!=null){try{mic.stop();}catch(Exception ignored){}mic.release();}synchronized(this){if(current==session)current=null;}}}
 void close(){stop("",false);audio.shutdown();}
}
